WITH daily_returns AS ( SELECT cr_returned_date_sk AS date_sk, COUNT(*) AS num_returns, SUM(cr_return_amount) AS total_return_amount, SUM(cr_fee) AS total_fee, SUM(cr_store_credit) AS total_store_credit, AVG(cr_return_quantity) AS avg_return_quantity FROM catalog_returns WHERE cr_fee > 20 GROUP BY cr_returned_date_sk ), daily_web AS ( SELECT wp_access_date_sk AS date_sk, COUNT(*) AS num_page_accesses, SUM(wp_image_count) AS total_images, AVG(wp_char_count) AS avg_char_count, COUNT(DISTINCT wp_web_page_id) AS distinct_pages FROM web_page WHERE wp_type = 'product' GROUP BY wp_access_date_sk ) SELECT r.date_sk, r.num_returns, r.total_return_amount, r.total_fee, r.total_store_credit, w.num_page_accesses, w.total_images, r.total_return_amount / NULLIF(w.total_images, 0) AS return_per_image, SUM(r.total_return_amount) OVER (ORDER BY r.date_sk) AS cumulative_return, ROW_NUMBER() OVER (ORDER BY r.total_return_amount DESC) AS return_rank FROM daily_returns r JOIN daily_web w ON r.date_sk = w.date_sk WHERE r.total_return_amount > 1000 ORDER BY r.total_return_amount DESC LIMIT 100
